import os
from IQCommon import pandas as pd
import numpy as np
from IQCommon.logger import system_log
from IQData.utils.datetime_func import int_convert_date
class TradingDayManager(object):
    def __init__(self, path):
        self._path = path
        if not os.path.exists(self._path):
            system_log.error('文件路径{}不存在.出错位置:trading_day_manager模块下的__init__方法'.format(os.path.abspath(self._path)))
            raise FileNotFoundError('文件路径{}不存在'.format(os.path.abspath(self._path)))
        self._dates = pd.read_pickle(self._path)
    def get_trading_day(self, start_date=None, end_date=None):
        if start_date is None:
            start_pos = 0
        else:
            start_pos = self._dates.searchsorted(int_convert_date(start_date), side='left')
        if end_date is None:
            end_pos = None
        else:
            end_pos = self._dates.searchsorted(int_convert_date(end_date), side='right')
        return self._dates[start_pos:end_pos].tolist()
    def numpy_find_pos(self, ndarray, item):
        pos = np.argwhere(ndarray == item)
        if len(pos):
            return int(pos)
    def numpy_delete(self, ndarray, item):
        pos = self.numpy_find_pos(ndarray, item)
        if pos is not None:
            ndarray = np.delete(ndarray, pos)
            system_log.info('从数组中成功删除{}.'.format(item))
        else:
            system_log.error('数组中不存在元素{},删除失败'.format(item))
        return ndarray
    def numpy_insert(self, ndarray, base_item, insert_item):
        pos = self.numpy_find_pos(ndarray, base_item)
        if pos is not None:
            ndarray = np.insert(ndarray, pos, insert_item)
            system_log.info('从数组中成功插入{}.'.format(insert_item))
        else:
            system_log.error('数组中不存在元素{},插入失败'.format(base_item))
        return ndarray
    def numpy_edit(self, ndarray, base_item, edit_item):
        pos = self.numpy_find_pos(ndarray, base_item)
        if pos is not None:
            ndarray[pos] = edit_item
            system_log.info('数组中成功修改为{}.'.format(edit_item))
        else:
            system_log.error('数组中不存在元素{},修改失败'.format(base_item))
        return ndarray
    def trading_day_delete(self, dt):
        dates = self._dates
        if isinstance(dt, int):
            dt = int_convert_date(dt)
            dates = self.numpy_delete(dates, dt)
        elif isinstance(dt, list):
            for d in dt:
                d = int_convert_date(d)
                dates = self.numpy_delete(dates, d)
        return dates
    def trading_day_insert(self, base_dt, insert_dt):
        dates = self._dates
        if isinstance(insert_dt, int):
            base_dt = int_convert_date(base_dt)
            insert_dt = int_convert_date(insert_dt)
            dates = self.numpy_insert(dates, base_dt, insert_dt)
        elif isinstance(insert_dt, list):
            base_dt = int_convert_date(base_dt)
            insert_dt = [int_convert_date(d) for d in insert_dt]
            dates = self.numpy_insert(dates, base_dt, insert_dt)
        return dates
    def trading_day_edit(self, base_dt, edit_dt):
        dates = self._dates
        if isinstance(base_dt, int) and isinstance(edit_dt, int):
            base_dt = int_convert_date(base_dt)
            edit_dt = int_convert_date(edit_dt)
            dates = self.numpy_edit(dates, base_dt, edit_dt)
        elif isinstance(base_dt, list) and isinstance(edit_dt, list):
            base_dt = [int_convert_date(d) for d in base_dt]
            edit_dt = [int_convert_date(d) for d in edit_dt]
            for i in range(len(base_dt)):
                dates = self.numpy_edit(dates, base_dt[i], edit_dt[i])
        return dates
    def trading_day_append(self, apend_dt):
        dates = self._dates
        if isinstance(apend_dt, int):
            apend_dt = int_convert_date(apend_dt)
            dates = np.append(dates, apend_dt)
        elif isinstance(apend_dt, list):
            apend_dt = [int_convert_date(d) for d in apend_dt]
            dates = np.append(dates, apend_dt)
        return dates
    def trading_day_append_from_file(self, incre_file_path):
        incre_df = pd.read_csv(incre_file_path)
        incre_df['trading_day'] = incre_df['trading_day'].map(lambda x: self.int_convert_date(x))
        inc_nd = incre_df['trading_day'].values
        new_nd = np.append(self._dates, inc_nd)
        return new_nd
    def trading_day_dump(self, dates, file_path):
        pd.to_pickle(dates, file_path, protocol=4)
    def trading_day_load(self, file_path):
        dates = pd.read_pickle(file_path)
        return dates
